BEGIN;
-- Generated by scripts/generate_schema.py. Apply once in migration order.
CREATE SCHEMA inventory;
CREATE SCHEMA inventory_security;
REVOKE ALL ON SCHEMA inventory,inventory_security FROM PUBLIC;
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='inventory_runtime') THEN
 CREATE ROLE inventory_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF;
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='inventory_auth') THEN
 CREATE ROLE inventory_auth NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF;
END $$;
-- Existing roles must have safe attributes; never silently trust pre-existing privileges.
DO $$ BEGIN
 IF EXISTS(SELECT FROM pg_roles WHERE rolname IN ('inventory_runtime','inventory_auth')
 AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolreplication)) THEN
 RAISE EXCEPTION 'Unsafe pre-existing application role'; END IF;
 IF EXISTS(SELECT FROM pg_auth_members am JOIN pg_roles r ON r.oid=am.member WHERE r.rolname IN ('inventory_runtime','inventory_auth')) THEN
 RAISE EXCEPTION 'Application group roles must not inherit other roles'; END IF;
END $$;
GRANT USAGE ON SCHEMA inventory,inventory_security TO inventory_runtime,inventory_auth;
ALTER DEFAULT PRIVILEGES IN SCHEMA inventory REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA inventory_security REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
CREATE FUNCTION inventory_security.tenant_id() RETURNS uuid LANGUAGE sql STABLE
 SET search_path=pg_catalog AS $$SELECT nullif(current_setting('app.tenant_id',true),'')::uuid$$;
CREATE FUNCTION inventory_security.user_id() RETURNS uuid LANGUAGE sql STABLE
 SET search_path=pg_catalog AS $$SELECT nullif(current_setting('app.user_id',true),'')::uuid$$;
REVOKE ALL ON FUNCTION inventory_security.tenant_id(),inventory_security.user_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION inventory_security.tenant_id(),inventory_security.user_id() TO inventory_runtime,inventory_auth;

CREATE TABLE inventory.tenants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE CHECK(code ~ '^[A-Z0-9_-]{2,40}$'),
  name text NOT NULL,
  status text NOT NULL DEFAULT 'provisioning' CHECK(status IN ('provisioning','setup','active','inactive')),
  timezone text NOT NULL DEFAULT 'Asia/Jakarta',
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0)
);

CREATE TABLE inventory.app_users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sso_user_id text NOT NULL UNIQUE CHECK(sso_user_id ~ '^[a-zA-Z0-9_.:-]{1,160}$'),
  username_snapshot text NOT NULL,
  full_name_snapshot text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0)
);

CREATE TABLE inventory.permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  description text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE inventory.roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT,
  code text NOT NULL CHECK(code IN ('admin','petugas','viewer')),
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id,code)
);

CREATE INDEX ON inventory.roles(tenant_id,created_at,id);

CREATE TABLE inventory.role_permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT,
  role_id uuid NOT NULL,
  permission_code text NOT NULL REFERENCES inventory.permissions(code),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  FOREIGN KEY(tenant_id,role_id) REFERENCES inventory.roles(tenant_id,id) ON DELETE RESTRICT,
  UNIQUE(tenant_id,role_id,permission_code)
);

CREATE INDEX ON inventory.role_permissions(tenant_id,created_at,id);

CREATE INDEX ON inventory.role_permissions(tenant_id,role_id);

CREATE TABLE inventory.tenant_memberships (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT,
  app_user_id uuid NOT NULL REFERENCES inventory.app_users(id),
  role_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','revoked')),
  authorization_version bigint NOT NULL DEFAULT 1 CHECK(authorization_version>0),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  FOREIGN KEY(tenant_id,role_id) REFERENCES inventory.roles(tenant_id,id) ON DELETE RESTRICT,
  UNIQUE(tenant_id,app_user_id),
  UNIQUE(tenant_id,id,app_user_id)
);

CREATE INDEX ON inventory.tenant_memberships(tenant_id,created_at,id);

CREATE INDEX ON inventory.tenant_memberships(tenant_id,role_id);

