  FOREIGN KEY(tenant_id,granted_by) REFERENCES inventory.tenant_memberships(tenant_id,id) ON DELETE RESTRICT,
  UNIQUE(tenant_id,membership_id,permission_code)
);

CREATE INDEX ON inventory.membership_permission_grants(tenant_id,created_at,id);

