  currency text NOT NULL DEFAULT 'IDR' CHECK(currency ~ '^[A-Z]{3}$'),
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  max_upload_bytes bigint NOT NULL DEFAULT 20971520 CHECK(max_upload_bytes BETWEEN 1 AND 104857600),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  UNIQUE(tenant_id)
);

CREATE INDEX ON inventory.tenant_settings(tenant_id,created_at,id);

CREATE TABLE inventory.app_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_digest text NOT NULL UNIQUE CHECK(token_digest ~ '^[0-9a-f]{64}$'),
  app_user_id uuid NOT NULL REFERENCES inventory.app_users(id),
  active_tenant_id uuid,
  active_membership_id uuid,
  identity_version bigint NOT NULL CHECK(identity_version>0),
  authorization_version bigint CHECK(authorization_version>0),
  authenticated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  expires_at timestamptz NOT NULL,
  idle_expires_at timestamptz NOT NULL,
  last_seen_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  last_sso_check_at timestamptz NOT NULL,
  revoked_at timestamptz,
  FOREIGN KEY(active_tenant_id,active_membership_id,app_user_id) REFERENCES inventory.tenant_memberships(tenant_id,id,app_user_id),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  CHECK((active_tenant_id IS NULL)=(active_membership_id IS NULL)),
  CHECK((active_tenant_id IS NULL)=(authorization_version IS NULL)),
  CHECK(expires_at>authenticated_at),
  CHECK(idle_expires_at<=expires_at),
  CHECK(idle_expires_at>authenticated_at)
);

CREATE INDEX ON inventory.app_sessions(app_user_id) WHERE revoked_at IS NULL;

CREATE TABLE inventory.platform_operator_grants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
