CREATE TABLE inventory.assets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT,
  inventory_code text NOT NULL,
  public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
  name text NOT NULL,
  category_id uuid NOT NULL,
  subcategory_id uuid,
  unit_id uuid NOT NULL,
  funding_source_id uuid,
  room_id uuid,
  responsible_membership_id uuid,
  condition_id uuid NOT NULL,
  lifecycle_status text NOT NULL DEFAULT 'draft' CHECK(lifecycle_status IN ('draft','available','reserved','on_loan','maintenance','disposed','archived')),
  brand text,
  model text,
  serial_number text,
  specifications jsonb NOT NULL DEFAULT '{}'::jsonb,
  acquisition_date date NOT NULL,
  in_service_date date,
  acquisition_method text NOT NULL,
  acquisition_cost numeric(20,2) NOT NULL CHECK(acquisition_cost>=0),
  residual_value numeric(20,2) NOT NULL DEFAULT 0 CHECK(residual_value>=0),
  useful_life_months integer CHECK(useful_life_months>0),
  depreciation_policy_id uuid,
  notes text,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  FOREIGN KEY(tenant_id,category_id) REFERENCES inventory.asset_categories(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,subcategory_id) REFERENCES inventory.asset_subcategories(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,unit_id) REFERENCES inventory.units(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,funding_source_id) REFERENCES inventory.funding_sources(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,room_id) REFERENCES inventory.rooms(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,responsible_membership_id) REFERENCES inventory.tenant_memberships(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,condition_id) REFERENCES inventory.asset_conditions(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,depreciation_policy_id) REFERENCES inventory.depreciation_policies(tenant_id,id) ON DELETE RESTRICT,
  CHECK(residual_value<=acquisition_cost),
  UNIQUE(tenant_id,inventory_code)
);

