  payload_snapshot jsonb NOT NULL,
  status text NOT NULL CHECK(status IN ('pending','partially_approved','approved','rejected','revision_required','cancelled')),
  current_level integer NOT NULL DEFAULT 1 CHECK(current_level>0),
  finalized_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  FOREIGN KEY(tenant_id,document_id) REFERENCES inventory.business_documents(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,workflow_version_id) REFERENCES inventory.approval_workflow_versions(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,requested_by) REFERENCES inventory.tenant_memberships(tenant_id,id) ON DELETE RESTRICT,
  UNIQUE(tenant_id,document_id,document_revision)
);

