  FOREIGN KEY(tenant_id,to_membership_id) REFERENCES inventory.tenant_memberships(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,workflow_id) REFERENCES inventory.approval_workflows(tenant_id,id) ON DELETE RESTRICT,
  CHECK(ends_at>starts_at),
  CHECK(from_membership_id<>to_membership_id)
);

