CREATE TABLE inventory.tenant_drive_connections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT,
  auth_mode text NOT NULL CHECK(auth_mode IN ('oauth','service_account')),
  connection_version integer NOT NULL CHECK(connection_version>0),
  root_folder_id text NOT NULL,
  drive_id text,
  google_identity text NOT NULL,
  token_ciphertext text,
  encryption_key_id text,
  status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','revoked','failed','retired')),
