  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  CHECK(auth_mode<>'oauth' OR (token_ciphertext IS NOT NULL AND encryption_key_id IS NOT NULL)),
  UNIQUE(tenant_id,connection_version)
);

