CREATE TABLE inventory.file_upload_operations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES inventory.tenants(id) ON DELETE RESTRICT,
  file_id uuid NOT NULL,
  actor_id uuid NOT NULL,
  idempotency_key text NOT NULL,
  resumable_uri_ciphertext text,
  encryption_key_id text,
  expected_size bigint NOT NULL CHECK(expected_size>0),
  confirmed_offset bigint NOT NULL DEFAULT 0 CHECK(confirmed_offset>=0),
  lease_token_digest text,
  lease_expires_at timestamptz,
  expires_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','uploading','verifying','ready','failed','expired')),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0),
  UNIQUE(tenant_id,id),
  FOREIGN KEY(tenant_id,file_id) REFERENCES inventory.file_attachments(tenant_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tenant_id,actor_id) REFERENCES inventory.tenant_memberships(tenant_id,id) ON DELETE RESTRICT,
  CHECK(confirmed_offset<=expected_size),
  CHECK(status<>'ready' OR confirmed_offset=expected_size),
  UNIQUE(tenant_id,idempotency_key),
  UNIQUE(tenant_id,file_id)
);

